  .kasan.unused : { *(.data..LASANLOC*) }
  .kasan.global : { KEEP (*(.data..LASAN0)); KEEP (*(.data.rel.local..LASAN0)); }
  .kasan.shadows : { *(.kasan.shadows) }
#endif

  .text : {
      _stext = . ;
      *(.text) *(.text.*) *(.gnu.warning) *(.stub) *(.glue_7) *(.glue_7t) *(.jcr)
      *(.gnu.linkonce.t.*) *(.init) *(.fini)
      _etext = . ;
  }

  .rodata : {
      _srodata = . ;
      *(.rodata) *(.rodata1) *(.rodata.*) *(.gnu.linkonce.r*)
      _erodata = . ;
  }

  .tdata : { _stdata = ABSOLUTE(.); *(.tdata .tdata.* .gnu.linkonce.td.*); _etdata = ABSOLUTE(.); }
  .tbss  : { _stbss = ABSOLUTE(.); *(.tbss .tbss.* .gnu.linkonce.tb.* .tcommon); _etbss = ABSOLUTE(.); }
  _eronly = ABSOLUTE(.);

  .data : {
      _sdata = . ;
      *(.data) *(.data1) *(.data.*) *(.gnu.linkonce.d*)
      . = ALIGN(4);
      _edata = . ;
  }

  .bss : {
      _sbss = . ;
      *(.bss) *(.bss.*) *(.sbss) *(.sbss.*) *(.gnu.linkonce.b*) *(COMMON)
      . = ALIGN(32);
      _ebss = . ;
  } > ksram

  .pgtables (NOLOAD) : ALIGN(0x1000) {
      *(.pgtables)
      . = ALIGN(4);
  } > ksram

  .stack_top : {
      . = ALIGN(32);
      _ebss = ABSOLUTE(.);
  } > ksram

  /* Stabs debugging sections */
  .stab 0 : { *(.stab) }
  .stabstr 0 : { *(.stabstr) }
  .stab.excl 0 : { *(.stab.excl) }
  .stab.exclstr 0 : { *(.stab.exclstr) }
  .stab.index 0 : { *(.stab.index) }
  .stab.indexstr 0 : { *(.stab.indexstr) }
  .comment 0 : { *(.comment) }
  .debug_abbrev 0 : { *(.debug_abbrev) }
  .debug_info 0 : { *(.debug_info) }
  .debug_line 0 : { *(.debug_line) }
  .debug_pubnames 0 : { *(.debug_pubnames) }
  .debug_aranges 0 : { *(.debug_aranges) }
}

